use std::{collections::BTreeMap, sync::Arc};
use unisphere_sdk::query::*;
use unisphere_loader_query::{LocalQueryContext, LocalQuerySource, NativeRepresentation, QueryRegistration};
use unisphere_adapter_claude::{ClaudeAdapter, DESCRIPTOR, QUERY_POLICY_VERSION};
use unisphere_output_query::ProjectedQueryWriter;

fn request(scope: QueryScope, dataset: Dataset, operation: Operation) -> QueryRequest {
    QueryRequest { dataset, operation, scope, filters: Vec::new(), time: TimeWindow::default(),
        branch: None, turn_range: None, sort: Vec::new(), columns: None, limit: Some(0),
        cursor: None, context: ContextWindow::default(), include_content: false,
        allow_partial: false, unresolved: UnresolvedPolicy::Reject, limits: QueryLimits::default() }
}
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let temp = tempfile::tempdir()?;
    let file = temp.path().join("session.jsonl");
    let cwd = temp.path().to_str().unwrap();
    let records = [
        serde_json::json!({"type":"user","sessionId":"smoke-session","uuid":"u1","cwd":cwd,"timestamp":"2026-09-01T12:00:00Z","message":{"role":"user","content":"PRIVATE-SMOKE-PROMPT"}}),
        serde_json::json!({"type":"assistant","sessionId":"smoke-session","uuid":"a1","parentUuid":"u1","cwd":cwd,"timestamp":"2026-09-01T12:00:01Z","message":{"role":"assistant","content":[{"type":"tool_use","id":"call-1","name":"Bash","input":{"command":"PRIVATE-SMOKE-COMMAND"}}]}}),
        serde_json::json!({"type":"user","sessionId":"smoke-session","uuid":"r1","parentUuid":"a1","cwd":cwd,"timestamp":"2026-09-01T12:00:02Z","message":{"role":"user","content":[{"type":"tool_result","tool_use_id":"call-1","content":"PRIVATE-SMOKE-RESULT","is_error":false}]}}),
    ];
    let input = records.iter().map(|r| serde_json::to_string(r).unwrap()).collect::<Vec<_>>().join("\n") + "\n";
    std::fs::write(&file, input)?;
    let registration = QueryRegistration::new(DESCRIPTOR, HarnessId::new("claude-code")?, NativeRepresentation::Jsonl, Arc::new(ClaudeAdapter))
        .with_query_policy_version(QUERY_POLICY_VERSION);
    let source = LocalQuerySource::new(vec![registration], LocalQueryContext::new(std::env::consts::OS, BTreeMap::new()));
    let service = QueryService::new(source);
    let scope = QueryScope::Source { selector: SourceSelector::Path { path: file, adapter: Some(AdapterId::new(DESCRIPTOR.id)?) } };
    let session_query = request(scope.clone(), Dataset::Sessions, Operation::List);
    let sessions = service.execute(&session_query)?;
    assert_eq!(sessions.matched, 1);
    let view = service.open_view(&request(scope.clone(), Dataset::Tools, Operation::List))?;
    let tools = execute_view(&view, &request(scope.clone(), Dataset::Tools, Operation::List))?;
    assert_eq!(tools.matched, 1);
    let stats_query = request(scope.clone(), Dataset::Tools, Operation::Stats { group_by: vec![FieldId::ToolFamily], metrics: vec![Metric::Count, Metric::MeanMs, Metric::Failures] });
    let stats = execute_view(&view, &stats_query)?;
    assert_eq!(stats.rows.len(), 1);
    assert!(matches!(stats.rows[0].field(FieldId::Count), Some(FieldValue::Unsigned(1))));
    assert!(matches!(stats.rows[0].field(FieldId::MeanMs), Some(FieldValue::Float(ms)) if *ms == 1000.0));
    assert!(matches!(stats.rows[0].field(FieldId::Failures), Some(FieldValue::Unsigned(0))));
    let mut bytes = Vec::new();
    ProjectedQueryWriter.write(&stats, &QueryOutputOptions { format: OutputFormat::Jsonl, csv_safety: CsvSafety::Spreadsheet, max_output_bytes: 4096, next_action: RenderedAction { summary: "Inspect matched tools".into(), argv: Vec::new(), required_inputs: Vec::new() } }, &mut bytes)?;
    let text = String::from_utf8(bytes)?;
    let row: serde_json::Value = serde_json::from_str(text.trim_end())?;
    assert_eq!(row["count"], 1);
    assert_eq!(row["mean_ms"], 1000.0);
    assert!(row.get("next_action").is_none());
    assert!(!text.contains("PRIVATE-SMOKE"));
    println!("{}", serde_json::json!({"scope":"real external SDK + local JSONL loader + Claude adapter + query writer","sessions":sessions.matched,"tools":tools.matched,"mean_ms":row["mean_ms"],"clean_jsonl":true,"private_payload_omitted":true,"cli_implemented":false}));
    Ok(())
}

